 private UsernamePasswordAuthenticationToken auth(Long u,Long i,String... permisos){var a=Arrays.stream(permisos).map(SimpleGrantedAuthority::new).toList();return new UsernamePasswordAuthenticationToken(new UsuarioPrincipal(u,i,Set.of(),true,false,"qa.borradores","",a),"",a);}
 private UsernamePasswordAuthenticationToken completo(){return auth(100000L,100000L,"EMPLEADO_LEER","EMPLEADO_LABORAL_LEER","CONDICION_SALARIAL_ADMINISTRAR");}
 private void sesion(){SecurityContextHolder.getContext().setAuthentication(completo());}
 private MockHttpSession web(UsernamePasswordAuthenticationToken a){var session=new MockHttpSession();session.setAttribute("SPRING_SECURITY_CONTEXT",new SecurityContextImpl(a));return session;}
 private FiltroNomina filtro(Long empleado){return new FiltroNomina("","TODOS",null,null,null,null,empleado,null,null,null,0,25);}
 private Long periodo(ProgramacionNominaService p,Long cal,String codigo,LocalDate inicio,LocalDate fin){var c=p.contexto(cal);var f=new PeriodoNominaForm();f.setCalendarioId(cal);f.setCalendarioTexto(c.calendario());f.setCalendarioVersion(c.version());f.setCodigo(codigo);f.setNombre(codigo+" de prueba");f.setInicio(inicio);f.setFin(fin);f.setPago(fin);f.setMotivo("Ensayo de programación sin pagos");return p.guardarPeriodo(null,f);}
 private BorradorNominaForm captura(PreparacionNominaService s,Long periodo,Long empleado){var f=new BorradorNominaForm();f.setPeriodoId(periodo);f.setSelloPeriodo(s.contexto(periodo).sello());f.setNombre("Preparación ficticia de enero");f.setMotivo("Borrador ficticio, no autorizado ni pagado");f.setSeleccion(s.candidatos(periodo,filtro(empleado),"LISTO").getContent().stream().map(PreparacionNominaService.Candidato::token).toList());return f;}
