  var html=mvc.perform(get("/admin/preparacion-nomina/vista/"+vista).session(session)).andReturn().getResponse();assertThat(html.getStatus()).isEqualTo(200);Files.writeString(dir.resolve("global.html"),html.getContentAsString());
  var individualHtml=mvc.perform(get("/admin/preparacion-nomina/vista/"+vista+"/empleados/200129").session(session)).andReturn().getResponse();assertThat(individualHtml.getStatus()).isEqualTo(200);Files.writeString(dir.resolve("global-empleado.html"),individualHtml.getContentAsString());
